        [L3("Halve violent crime (2024 manifesto): police is an ANC portfolio; untested at national level", "Réduire de moitié la criminalité violente (manifeste 2024) : la police est un portefeuille de l'ANC ; non testé au niveau national", "Reducir a la mitad la delincuencia violenta (manifiesto de 2024): la policía es una cartera del ANC; sin probar a nivel nacional"), "untested", null]
