        [L3("Nationalise the Reserve Bank and the big banks: never in government", "Nationaliser la Banque de réserve et les grandes banques : jamais au gouvernement", "Nacionalizar el Banco de la Reserva y la gran banca: nunca en el gobierno"), "untested", null]
